"""Returns, discounting and the Bellman expectation equation on a noisy grid world.

Grid (3 rows x 4 columns), wall at (1,1), +1 exit at (0,3), -1 exit at (1,3), start bottom-left.
Actions N/E/S/W succeed 80%; 10% slip to each side; bumping a wall or the edge = stay.
Every non-exit step gives a living reward r_live. We evaluate the equiprobable random policy
exactly by solving the linear Bellman system v = r_pi + gamma * P_pi v.
"""
import numpy as np

def G(rewards, gamma):
    return sum(gamma ** k * r for k, r in enumerate(rewards))
print("G([1,2,3], 0.5) =", G([1, 2, 3], 0.5), "| G([3,2,1], 0.5) =", G([3, 2, 1], 0.5))
print("+1 forever, gamma 0.9: 1/(1-0.9) =", round(1 / (1 - 0.9), 6), "| partial sum of 500 terms:", round(G([1] * 500, 0.9), 6))

ROWS, COLS, WALL, EXITS = 3, 4, (1, 1), {(0, 3): 1.0, (1, 3): -1.0}
STATES = [(r, c) for r in range(ROWS) for c in range(COLS) if (r, c) != WALL]
IDX = {s: i for i, s in enumerate(STATES)}
MOVES = {"N": (-1, 0), "E": (0, 1), "S": (1, 0), "W": (0, -1)}
SIDE = {"N": "WE", "S": "EW", "E": "NS", "W": "SN"}

def move(s, a):
    r, c = s[0] + MOVES[a][0], s[1] + MOVES[a][1]
    return s if not (0 <= r < ROWS and 0 <= c < COLS) or (r, c) == WALL else (r, c)

def transitions(s, a):
    """list of (prob, next_state) with 80/10/10 slip"""
    return [(0.8, move(s, a)), (0.1, move(s, SIDE[a][0])), (0.1, move(s, SIDE[a][1]))]

def evaluate_random(gamma, r_live):
    n = len(STATES); P = np.zeros((n, n)); R = np.zeros(n)
    for s in STATES:
        i = IDX[s]
        if s in EXITS: R[i] = EXITS[s]; continue          # exit: collect reward, episode ends
        for a in MOVES:
            for p, s2 in transitions(s, a):
                P[i, IDX[s2]] += 0.25 * p
        R[i] = r_live
    return np.linalg.solve(np.eye(n) - gamma * P, R)

v = evaluate_random(0.9, -0.04)
print("\nRandom-policy values (gamma 0.9, living reward -0.04):")
for r in range(ROWS):
    print("  " + "  ".join("  wall" if (r, c) == WALL else f"{v[IDX[(r, c)]]:6.3f}" for c in range(COLS)))
s = (2, 2); i = IDX[s]
backup = -0.04 + 0.9 * sum(0.25 * p * v[IDX[s2]] for a in MOVES for p, s2 in transitions(s, a))
print(f"check Bellman at {s}: v = {v[i]:.4f}, one backup from neighbours = {backup:.4f}")

print("\nWorked backup: 0.25 * 0.9 * (2.3 + 0.7 - 0.4 + 0.4) =", round(0.25 * 0.9 * (2.3 + 0.7 - 0.4 + 0.4), 4))

"""Bellman optimality: optimal values and policies of the noisy grid world for several living rewards.

v*(s) = max_a sum_s' p(s'|s,a) [r + gamma v*(s')], found by repeated optimality backups.
Changing the per-step (living) reward changes the optimal policy: in an episodic task,
adding a constant to every reward is NOT harmless.
"""
import numpy as np
ROWS, COLS, WALL, EXITS = 3, 4, (1, 1), {(0, 3): 1.0, (1, 3): -1.0}
MOVES = {"N": (-1, 0), "E": (0, 1), "S": (1, 0), "W": (0, -1)}
SIDE = {"N": "WE", "S": "EW", "E": "NS", "W": "SN"}
ARROW = {"N": "^", "E": ">", "S": "v", "W": "<"}
STATES = [(r, c) for r in range(ROWS) for c in range(COLS) if (r, c) != WALL]
def move(s, a):
    r, c = s[0] + MOVES[a][0], s[1] + MOVES[a][1]
    return s if not (0 <= r < ROWS and 0 <= c < COLS) or (r, c) == WALL else (r, c)
def T(s, a): return [(0.8, move(s, a)), (0.1, move(s, SIDE[a][0])), (0.1, move(s, SIDE[a][1]))]

def solve(r_live, gamma=1.0, tol=1e-10):
    V = {s: 0.0 for s in STATES}
    for sweep in range(10000):
        delta = 0
        for s in STATES:
            if s in EXITS: new = EXITS[s]
            else: new = max(r_live + gamma * sum(p * V[s2] for p, s2 in T(s, a)) for a in MOVES)
            delta = max(delta, abs(new - V[s])); V[s] = new
        if delta < tol: break
    pi = {s: max(MOVES, key=lambda a: sum(p * V[s2] for p, s2 in T(s, a))) for s in STATES if s not in EXITS}
    return V, pi, sweep + 1

for r_live in (-0.04, -0.4, -2.0, 0.5):
    gamma = 1.0 if r_live < 0 else 0.9          # positive living reward needs discounting to stay finite
    V, pi, n = solve(r_live, gamma)
    print(f"living reward {r_live:+} (gamma {gamma}), converged in {n} sweeps:")
    for r in range(ROWS):
        row = []
        for c in range(COLS):
            s = (r, c)
            row.append("  #  " if s == WALL else (" +1  " if EXITS.get(s) == 1 else " -1  ") if s in EXITS else f"{ARROW[pi[s]]}{V[s]:5.2f}")
        print("   " + " ".join(row))
